func Run(args []string, stdout, stderr io.Writer) int {
	if len(args) > 0 && args[0] == completeCommand { // hidden: asked by the completion scripts
		return runComplete(args[1:], stdout)
	}
	if len(args) > 0 && (args[0] == "-v" || args[0] == "--version") {
		args = append([]string{"version"}, args[1:]...)
	}
	return dispatch(root(), []string{"harness"}, args, stdout, stderr)
}

func clientConfigFlags(verb string) func(fs *flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		client := fs.String("client", "all", "claude-code, codex or all")
		scope := fs.String("scope", clients.ScopeUser, "Claude Code scope: user (~/.claude.json), project (.mcp.json) or local"+
			map[string]string{"uninstall": "; 'all' for every scope"}[verb])
		dryRun := fs.Bool("dry-run", false, "show the changes without writing anything")
		projectDir := fs.String("project", ".", "repository for project/local scope")
		command := new(string)
		all, deleteData := new(bool), new(bool)
		if verb == "install" {
			command = fs.String("command", "", "harness executable to configure (default: this binary)")
		} else {
			all = fs.Bool("all", false, "remove everything harness added: MCP entries in every scope, hooks, agent instructions, shell completion")
			deleteData = fs.Bool("delete-data", false, "with --all: also delete this repository's .harness/ (memories, tasks, telemetry)")
		}
		return func(_ []string, stdout, stderr io.Writer) int {
			if fs.NFlag() == 0 { // bare: the setup wizard (TASK-0016)
				w := setupWizard("harness "+verb, *projectDir)
				if !isTerminal() {
					printWizardStatus(w, stdout)
					return ExitOK
				}
				return runWizard(w, stdout, stderr)
			}
			if *deleteData && !*all {
				fmt.Fprintln(stderr, "harness uninstall: --delete-data only goes with --all")
				return ExitUsage
			}
			if *deleteData && !flagSet(fs, "project") {
				// Deleting data is never aimed at a default: name the repository.
				fmt.Fprintln(stderr, "harness uninstall: --delete-data needs an explicit --project <repository>")
				return ExitUsage
			}
			if *all {
				return uninstallAll(*projectDir, *deleteData, *dryRun, stdout, stderr)
			}
			if verb == "install" && *scope == "all" {
				fmt.Fprintln(stderr, "harness install: choose one --scope (user, project or local)")
				return ExitUsage
			}

			root, err := projectRootFor(*projectDir, *scope)
			if err != nil {
				fmt.Fprintf(stderr, "harness %s: %v\n", verb, err)
				return ExitError
			}
			targets, err := clients.TargetsFor(*client, *scope, root)
			if err != nil {
				fmt.Fprintf(stderr, "harness %s: %v\n", verb, err)
				return ExitUsage
			}

			var spec clients.ServerSpec
			if verb == "install" {
				exe, err := harnessExecutable(*command)
				if err != nil {
					fmt.Fprintf(stderr, "harness install: %v\n", err)
					return ExitError
				}
				spec = clients.ServerSpec{Command: exe, Args: []string{"mcp"}}
			}

			failed := false
			for _, t := range targets {
				var ch clients.Change
				if verb == "install" {
					s := spec
					if t.Scope == clients.ScopeProject {
						s.Command = homeRelative(s.Command) // .mcp.json may be shared
					}
					ch, err = clients.Install(t, s, *dryRun)
				} else {
					ch, err = clients.Uninstall(t, *dryRun)
				}
				label := fmt.Sprintf("%s (%s) %s", t.Client, t.Scope, t.Path)
				if err != nil {
					failed = true
					fmt.Fprintf(stdout, "%s: error: %v\n", label, err)
					continue
				}
				printEdit(stdout, label, serverWords, ch.Change, *dryRun)
			}

			if *dryRun {
				fmt.Fprintln(stdout, "\nDry run: nothing was written.")
			} else if verb == "install" && !failed {
				fmt.Fprintln(stdout, "\nRestart Claude Code / Codex sessions to pick up changes.")
			}
			if failed {
				return ExitError
			}
			return ExitOK
		}
	}
}

func completionChangeFlags(on bool) func(*flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		shell := fs.String("shell", "", "zsh, bash, fish or pwsh (default: $SHELL; PowerShell on Windows)")
		return func(_ []string, stdout, stderr io.Writer) int {
			sh := *shell
			if sh == "" {
				sh = detectShell()
			}
			if sh == "" {
				fmt.Fprintln(stderr, "harness completion: cannot tell the shell from $SHELL; pass --shell zsh|bash|fish|pwsh")
				return ExitUsage
			}
			did, err := setCompletion(sh, on)
			if err != nil {
				fmt.Fprintf(stderr, "harness completion: %v\n", err)
				return ExitError
			}
			switch {
			case did != "":
				fmt.Fprintf(stdout, "%s: %s\n", sh, did)
			case on:
				fmt.Fprintf(stdout, "%s: already installed\n", sh)
			default:
				fmt.Fprintf(stdout, "%s: not installed\n", sh)
			}
			return ExitOK
		}
	}
}

func completionCommand() command {
	print := func(sh string) command {
		return command{name: sh, summary: "Print the " + sh + " completion script",
			flags: func(*flag.FlagSet) action {
				return func(_ []string, stdout, _ io.Writer) int {
					fmt.Fprint(stdout, completionScript(sh))
					return ExitOK
				}
			}}
	}
	return command{name: "completion", summary: "Shell completion: print, install or remove it (zsh, bash, fish, PowerShell)",
		about: "install adds a marked block to ~/.zshrc, ~/.bashrc or PowerShell's profile ($PROFILE.CurrentUserAllHosts; backed up first) " +
			"or a file in fish's completions directory; " +
			"uninstall removes only that. The scripts ask harness itself for candidates, so they never go stale.",
		subs: []command{
			{name: "status", summary: "Show where completion is installed (the default)", flags: completionStatusFlags},
			{name: "install", summary: "Set up completion for a shell (default: $SHELL)", flags: completionChangeFlags(true)},
			{name: "uninstall", summary: "Remove the completion harness set up", flags: completionChangeFlags(false)},
			print("zsh"), print("bash"), print("fish"), print("pwsh"),
		},
		defaultSub: "status"}
}

func completionStatusFlags(*flag.FlagSet) action {
	return func(_ []string, stdout, stderr io.Writer) int {
		for _, sh := range offeredShells() {
			ok, path, err := completionInstalled(sh)
			state := "not installed"
			switch {
			case err != nil:
				state = "unknown: " + err.Error()
			case ok:
				state = "installed"
			}
			mark := ""
			if sh == detectShell() {
				mark = " (your shell)"
			}
			fmt.Fprintf(stdout, "%-5s %-14s %s%s\n", sh, state, path, mark)
		}
		return ExitOK
	}
}

func contextCommand() command {
	return command{name: "context", summary: "How often get_context contained what the work then changed (stats)",
		subs: []command{{name: "stats", summary: "Hit rate of get_context answers against the commits that followed",
			about: "How often get_context answers contained the files the following commits\n" +
				"changed: overall, per provider x capability x language, and the files no\n" +
				"provider surfaced. Answers are scored when HEAD moves on (harness sync) or a\n" +
				"task completes with a commit.",
			flags: contextStatsFlags}}}
}

func contextStatsFlags(fs *flag.FlagSet) action {
	days := fs.Int("days", 30, "window in days")
	projectDir, asJSON := projectFlags(fs)
	return func(_ []string, stdout, stderr io.Writer) int {
		db, closeDB, err := openProjectDB(*projectDir)
		if err != nil {
			fmt.Fprintf(stderr, "harness context stats: %v\n", err)
			return ExitError
		}
		defer closeDB()
		st, err := telemetry.Report(context.Background(), db, time.Now().Add(-time.Duration(*days)*24*time.Hour))
		if err != nil {
			fmt.Fprintf(stderr, "harness context stats: %v\n", err)
			return ExitError
		}
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(st)
			return ExitOK
		}
		printContextStats(stdout, st, *days)
		return ExitOK
	}
}

func dispatch(c command, path, args []string, stdout, stderr io.Writer) int {
	name := strings.Join(path, " ")
	if c.subs != nil {
		if len(args) == 0 || (c.defaultSub != "" && strings.HasPrefix(args[0], "-") && !isHelp(args[0])) {
			if c.defaultSub == "" {
				printGroupUsage(stdout, c, name)
				return ExitOK
			}
			args = append([]string{c.defaultSub}, args...) // "projects --json" is "projects list --json"
		}
		if isHelp(args[0]) {
			// "<group> help <sub...>" is "<group> <sub...> --help".
			rest := slices.DeleteFunc(slices.Clone(args[1:]), isHelp)
			if len(rest) == 0 {
				printGroupUsage(stdout, c, name)
				return ExitOK
			}
			args = append(rest, "--help")
		}
		sub, ok := find(c.subs, args[0])
		if !ok {
			fmt.Fprintf(stderr, "%s: unknown command %q%s\nRun '%s help' for usage.\n", name, args[0], suggest(c.subs, args[0]), name)
			return ExitUsage
		}
		return dispatch(sub, append(slices.Clone(path), sub.name), args[1:], stdout, stderr)
	}
	if c.raw != nil {
		return c.raw(args, stdout, stderr)
	}

	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	run := c.flags(fs)
	if wantsHelp(args) {
		printLeafUsage(stdout, c, name, fs)
		return ExitOK
	}
	pos, err := parseInterspersed(fs, args)
	switch {
	case err != nil:
	case len(pos) < c.minArgs:
		err = fmt.Errorf("missing %s", c.args)
	case c.maxArgs >= 0 && len(pos) > c.maxArgs:
		err = fmt.Errorf("unexpected argument %q", pos[c.maxArgs])
	}
	if err != nil {
		fmt.Fprintf(stderr, "%s: %v\nRun '%s --help' for usage.\n", name, err, name)
		return ExitUsage
	}
	return run(pos, stdout, stderr)
}

func docsCommand() command {
	return command{name: "docs", summary: "Read the documentation: the 'Using harness' guide and the reference, by section",
		about: "Without a section it lists them; a section is named by its slug or a word of its title\n" +
			"(harness docs providers, harness docs guide). harness ui has the same on its Docs page.",
		args: "[section]", maxArgs: 1, flags: docsFlags}
}

func docsFlags(*flag.FlagSet) action {
	return func(args []string, stdout, stderr io.Writer) int {
		if len(args) == 0 {
			doc := ""
			for _, s := range docs.Sections() {
				if s.Doc != doc {
					doc = s.Doc
					for _, d := range docs.Docs {
						if d.Name == doc {
							fmt.Fprintf(stdout, "\n%s:\n", d.Title)
						}
					}
				}
				fmt.Fprintf(stdout, "  %-40s %s\n", s.Slug, s.Title)
			}
			fmt.Fprintln(stdout, "\nharness docs <section> prints one.")
			return ExitOK
		}
		s, ok := docs.Find(args[0])
		if !ok {
			fmt.Fprintf(stderr, "harness docs: no section %q (harness docs lists them)\n", args[0])
			return ExitUsage
		}
		fmt.Fprintln(stdout, strings.TrimSpace(s.Body))
		return ExitOK
	}
}

func doctorFlags(fs *flag.FlagSet) action {
	projectDir := fs.String("project", ".", "directory inside the repository to check")
	all := fs.Bool("all", false, "check every project in the machine registry (harness projects)")
	asJSON := fs.Bool("json", false, "machine-readable output")
	return func(_ []string, stdout, stderr io.Writer) int {
		if *all {
			return doctorAll(stdout, stderr, *asJSON)
		}
		checks := diagnose(*projectDir)
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(summarize(checks))
			return exitFor(checks)
		}
		width := 12 // provider names can be longer than the fixed check names
		for _, c := range checks {
			width = max(width, len(c.Name))
		}
		for _, c := range checks {
			printCheck(stdout, "", width, c)
		}
		fmt.Fprintln(stdout)
		fmt.Fprintln(stdout, summarize(checks).line())
		return exitFor(checks)
	}
}

func flagSet(fs *flag.FlagSet, name string) bool {
	set := false
	fs.Visit(func(f *flag.Flag) { set = set || f.Name == name })
	return set
}

func hookEventFlags(fs *flag.FlagSet) action {
	client := fs.String("client", clients.ClaudeCode, "client that runs the hook: claude-code or codex")
	return func(_ []string, _, stderr io.Writer) int {
		defer func() {
			if r := recover(); r != nil && os.Getenv("HARNESS_HOOK_DEBUG") != "" {
				fmt.Fprintf(stderr, "harness hook event: panic: %v\n", r)
			}
		}()
		ctx, cancel := context.WithTimeout(context.Background(), hookEventTimeout)
		defer cancel()
		// HARNESS_HOOK_DEBUG=1 says what happened: dropped and why, or
		// recorded (no output at all means the hook did not run)
		err := recordHookEvent(ctx, *client, os.Stdin, time.Now())
		if os.Getenv("HARNESS_HOOK_DEBUG") != "" {
			if err != nil {
				fmt.Fprintf(stderr, "harness hook event: dropped: %v\n", err)
			} else {
				fmt.Fprintln(stderr, "harness hook event: recorded")
			}
		}
		return ExitOK
	}
}

func hookSessionFlags(fs *flag.FlagSet) action {
	fs.String("client", clients.ClaudeCode, "client that runs the hook (claude-code)")
	return func(_ []string, stdout, _ io.Writer) int {
		var p struct {
			Cwd string `json:"cwd"`
		}
		payload, _ := io.ReadAll(io.LimitReader(os.Stdin, 1<<20))
		json.Unmarshal(payload, &p)
		dir := p.Cwd
		if dir == "" {
			dir = os.Getenv("CLAUDE_PROJECT_DIR")
		}
		if dir == "" {
			dir = "."
		}
		if _, _, err := harnessRepo(dir); err == nil {
			fmt.Fprintln(stdout, sessionContext)
		}
		return ExitOK
	}
}

func hooksChooseFlags(fs *flag.FlagSet) action {
	projectDir := fs.String("project", ".", "repository whose Git hooks to manage")
	scope := fs.String("scope", clients.ScopeUser, "where the client hooks go: user, project or local")
	return func(_ []string, stdout, stderr io.Writer) int {
		if !isTerminal() {
			return hooksFlagsRun("status", "all", *projectDir, *scope, "", false, stdout, stderr)
		}
		return runWizard(&wizard{title: "harness hooks", steps: []wizStep{hookStep(*projectDir, *scope)}}, stdout, stderr)
	}
}

func hooksFlags(verb string) func(fs *flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		defKind := hookGit
		if verb == "status" {
			defKind = "all"
		}
		kind := fs.String("kind", defKind, "hook kinds: git, claude-code, codex (comma-separated) or all")
		projectDir := fs.String("project", ".", "repository to update")
		scope := fs.String("scope", clients.ScopeUser, "client hooks: user, project or local"+
			map[string]string{"uninstall": "; 'all' for every scope"}[verb])
		var command *string
		dry := new(bool)
		if verb != "status" {
			dry = fs.Bool("dry-run", false, "show the changes without writing anything")
		}
		if verb == "install" {
			command = fs.String("command", "", "harness executable the hooks run (default: 'harness' for git, this binary for clients)")
		}
		return func(_ []string, stdout, stderr io.Writer) int {
			cmd := ""
			if command != nil {
				cmd = *command
			}
			return hooksFlagsRun(verb, *kind, *projectDir, *scope, cmd, *dry, stdout, stderr)
		}
	}
}

func initFlags(fs *flag.FlagSet) action {
	dryRun := fs.Bool("dry-run", false, "show what would be done without changing anything")
	projectDir := fs.String("project", ".", "directory inside the repository to initialize")
	return func(_ []string, stdout, stderr io.Writer) int {

		res, err := project.Init(context.Background(), *projectDir, *dryRun)
		if res != nil {
			printInitPlan(stdout, res)
		}
		if err != nil {
			fmt.Fprintf(stderr, "harness init: %v\n", err)
			return ExitError
		}

		if res.DryRun {
			fmt.Fprintln(stdout, "\nDry run: nothing was changed.")
			return ExitOK
		}
		reg := res.Registration
		fmt.Fprintln(stdout)
		switch {
		case reg.Created:
			fmt.Fprintf(stdout, "Initialized project %s (worktree %s).\n", reg.Project.ID, reg.Worktree.ID)
		case reg.Copied:
			fmt.Fprintf(stdout, "This is a copy of the project at %s: assigned new project %s (copied from %s).\n",
				reg.PreviousRoot, reg.Project.ID, reg.Project.CopiedFrom)
		case reg.Moved:
			fmt.Fprintf(stdout, "Project %s moved from %s; location updated.\n", reg.Project.ID, reg.PreviousRoot)
		default:
			fmt.Fprintf(stdout, "Already initialized: project %s (worktree %s).\n", reg.Project.ID, reg.Worktree.ID)
		}
		return ExitOK
	}
}

func instructionsFlags(fs *flag.FlagSet) action {
	remove := fs.Bool("remove", false, "remove the harness section (and CLAUDE.md's import of it) instead of adding/updating it")
	dryRun := fs.Bool("dry-run", false, "show the changes without writing anything")
	projectDir := fs.String("project", ".", "repository to update")
	return func(_ []string, stdout, stderr io.Writer) int {

		repo, err := git.Discover(*projectDir)
		if err != nil {
			fmt.Fprintf(stderr, "harness instructions: %v\n", err)
			return ExitError
		}
		var changes []instructions.Change
		if *remove {
			changes, err = instructions.RemoveProject(repo.Root, *dryRun)
		} else {
			// Codex reads only AGENTS.md: when it is set up for harness, the
			// guidance must be there even if the project has only a CLAUDE.md.
			changes, err = instructions.Project(repo.Root, clients.DetectClient(clients.Get(clients.Codex), "").Configured(), *dryRun)
		}
		for _, ch := range changes {
			if ch.Path == "" {
				continue
			}
			words := instructionWords
			if strings.Contains(string(ch.After), instructions.ImportBlock()) && ch.Action != fileedit.ActionRemove {
				words.thing = "import of " + instructions.File
			}
			printEdit(stdout, displayPath(repo.Root, ch.Path), words, ch.Change, *dryRun)
		}
		if err != nil {
			fmt.Fprintf(stderr, "harness instructions: %v\n", err)
			return ExitError
		}
		if *dryRun {
			fmt.Fprintln(stdout, "\nDry run: nothing was written.")
		}
		return ExitOK
	}
}

func isHelp(a string) bool {
	switch a {
	case "help", "-h", "-help", "--help":
		return true
	}
	return false
}

func mcpFlags(fs *flag.FlagSet) action {
	projectDir := fs.String("project", "", "project directory (default: current directory); resolved to its Git root")
	return func(_ []string, stdout, stderr io.Writer) int {

		loc, err := project.LocateOrDir(*projectDir)
		if err != nil {
			fmt.Fprintf(stderr, "harness mcp: %v\n", err)
			return ExitError
		}

		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()

		reg := builtin.Build(loc.Config, loc.Root)
		reg.Warm()
		srv := server.New(server.Options{ProjectRoot: loc.Root, StateRoot: loc.StateRoot, Repo: loc.Repo, Config: loc.Config, ConfigSources: loc.ConfigSources,
			Registry: reg})
		defer srv.Close()

		// Run returns when stdin reaches EOF or on a signal; both are normal
		// shutdowns for a stdio server.
		if err := srv.Run(ctx, server.NewStdioTransport(os.Stdin, os.Stdout)); err != nil && ctx.Err() == nil && !isClosedErr(err) {
			fmt.Fprintf(stderr, "harness mcp: %v\n", err)
			return ExitError
		}
		return ExitOK
	}
}

func memoryCommand() command {
	return command{name: "memory", summary: "Show a memory's history, or retire one that no longer applies",
		subs: []command{
			{name: "promote", summary: "Move a project memory up to a workspace or to every project of yours",
				args: "<id> --to workspace:<name>|user", minArgs: 1, maxArgs: 1, flags: memoryPromoteFlags},
			{name: "show", summary: "Show a memory with its supersession chain and audit trail",
				args: "<id>", minArgs: 1, maxArgs: 1, flags: memoryFlags("show")},
			{name: "retire", summary: "End a memory's validity now (it stops applying; nothing is deleted)",
				args: "<id>", minArgs: 1, maxArgs: 1, flags: memoryFlags("retire")},
		}}
}

func memoryFlags(verb string) func(fs *flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		projectDir, asJSON := projectFlags(fs)
		reason := new(string)
		if verb == "retire" {
			reason = fs.String("reason", "", "why it no longer applies (required)")
		}
		return func(args []string, stdout, stderr io.Writer) int {
			db, closeDB, err := openProjectDB(*projectDir)
			if err != nil {
				fmt.Fprintf(stderr, "harness memory %s: %v\n", verb, err)
				return ExitError
			}
			defer closeDB()
			ctx := context.Background()
			// A workspace or user memory is found in its level's store.
			l := memory.Layers{Project: memory.NewStore(db)}
			if f, err := workspace.Load(); err == nil {
				id := ""
				if p, err := registeredProject(*projectDir); err == nil {
					id = p.ID
				}
				if lv, err := workspace.OpenLevels(ctx, f, id); err == nil {
					defer lv.Close()
					l.Wider = lv.List
				}
			}
			store, level, err := l.Find(ctx, args[0])
			if err != nil {
				fmt.Fprintf(stderr, "harness memory %s: %v\n", verb, err)
				return ExitError
			}
			if verb == "retire" {
				if _, err := store.Retire(ctx, args[0], actor.Human(), *reason); err != nil {
					fmt.Fprintf(stderr, "harness memory retire: %v\n", err)
					return ExitError
				}
			}
			d, err := store.Details(ctx, args[0], true)
			if err != nil {
				fmt.Fprintf(stderr, "harness memory %s: %v\n", verb, err)
				return ExitError
			}
			if level != nil {
				d.Memory.Scope = level.String()
			}
			if *asJSON {
				enc := json.NewEncoder(stdout)
				enc.SetIndent("", "  ")
				enc.Encode(d)
				return ExitOK
			}
			printMemoryDetail(stdout, d)
			return ExitOK
		}
	}
}

func memoryPromoteFlags(fs *flag.FlagSet) action {
	projectDir, asJSON := projectFlags(fs)
	to := fs.String("to", "", "workspace:<name> or user (required)")
	force := fs.Bool("force", false, "record it even if the level holds a similar memory")
	return func(args []string, stdout, stderr io.Writer) int {
		fail := func(err error) int {
			fmt.Fprintf(stderr, "harness memory promote: %v\n", err)
			return ExitError
		}
		sc, err := memory.ParseScope(*to)
		if err != nil || !sc.Wider() {
			return fail(fmt.Errorf("--to must be workspace:<name> or user"))
		}
		p, err := registeredProject(*projectDir)
		if err != nil {
			return fail(err)
		}
		db, closeDB, err := openProjectDB(*projectDir)
		if err != nil {
			return fail(err)
		}
		defer closeDB()
		ctx := context.Background()
		res, err := workspace.Promote(ctx, memory.NewStore(db), p, args[0], sc, actor.Human(), *force, false)
		if err != nil {
			return fail(err)
		}
		if res.Status == memory.StatusNeedsDecision {
			fmt.Fprintf(stderr, "harness memory promote: %s already holds similar memories:\n", sc)
			for _, x := range res.Elsewhen {
				fmt.Fprintf(stderr, "  %s\n", x)
			}
			fmt.Fprintln(stderr, "Nothing changed. Run again with --force if this is a different statement.")
			return ExitError
		}
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(res)
			return ExitOK
		}
		fmt.Fprintf(stdout, "Promoted %s to %s as %s (retired here).\n", args[0], sc, res.Memory.ID)
		if len(res.HoldsIn) == 0 {
			fmt.Fprintln(stdout, "No other project records it yet.")
		} else {
			fmt.Fprintln(stdout, "It already holds in:")
			for _, h := range res.HoldsIn {
				fmt.Fprintf(stdout, "  %s  %s  %s\n", h.Project, h.Memory.ID, h.Memory.Content)
			}
			fmt.Fprintln(stdout, "Those projects keep their own copies, which take precedence there; retire them with 'harness memory retire <id> --project <dir>' to rely on the wider one.")
		}
		return ExitOK
	}
}

