func searchFlags(fs *flag.FlagSet) action {
	kind := fs.String("kind", "all", "symbol, text, file, callers, references, impact or all")
	inWorkspace := fs.Bool("workspace", false, "also search the other repositories in this project's workspaces")
	deep := fs.Bool("deep", false, "with --workspace: every provider of every member, heavy ones included (slower)")
	path := fs.String("path", "", "path prefix; with --workspace may be <project>:<path>")
	limit := fs.Int("limit", 10, "results per provider")
	projectDir, asJSON := projectFlags(fs)
	return func(args []string, stdout, stderr io.Writer) int {
		caps, ok := searchKinds[*kind]
		if !ok {
			fmt.Fprintln(stderr, "harness search: --kind must be symbol, text, file, callers, references, impact or all")
			return ExitUsage
		}
		if *deep && !*inWorkspace {
			fmt.Fprintln(stderr, "harness search: --deep goes with --workspace")
			return ExitUsage
		}
		query := strings.Join(args, " ")
		ws, closeWS, err := cliSearcher(*projectDir, *inWorkspace)
		if err != nil {
			fmt.Fprintf(stderr, "harness search: %v\n", err)
			return ExitError
		}
		defer closeWS()
		members := ws.Members
		only, pth := splitPathRef(*path, members)
		if *kind == "impact" && *inWorkspace && only == "" {
			return printImpact(ws, query, *limit, *deep, *asJSON, stdout)
		}
		var hits []wsearch.Hit
		var notes, errs []string
		for _, c := range caps {
			a := ws.Query(context.Background(), providers.Request{Capability: c, Query: query, Path: pth, Limit: *limit}, *deep, only)
			hits = append(hits, a.Hits...)
			notes = appendNew(notes, a.Notes...)
			errs = appendNew(errs, a.Errors...)
		}
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(map[string]any{"query": query, "hits": hits, "notes": notes, "errors": errs})
			return ExitOK
		}
		for _, h := range hits {
			loc := h.Item.Path
			if h.Item.StartLine > 0 {
				loc += fmt.Sprintf(":%d", h.Item.StartLine)
			}
			name := h.Item.Name
			if name == "" {
				name = strings.TrimSpace(h.Item.Snippet)
			}
			prefix := ""
			if *inWorkspace {
				prefix = h.Member.Name + ":"
			}
			fmt.Fprintf(stdout, "%s%-50s %-32s %s\n", prefix, loc, clip(name, 32), h.Item.Provider)
		}
		if len(hits) == 0 {
			fmt.Fprintln(stdout, "No results.")
		}
		for _, n := range notes {
			fmt.Fprintln(stdout, "note: "+n)
		}
		for _, e := range errs {
			fmt.Fprintln(stdout, "error: "+e)
		}
		return ExitOK
	}
}

func sessionsChange(verb string) func(*flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		projectDir := fs.String("project", ".", "the project whose session to "+verb)
		return func(args []string, stdout, stderr io.Writer) int {
			ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
			defer cancel()
			fail := func(err error) int {
				fmt.Fprintf(stderr, "harness providers sessions %s: %v\n", verb, err)
				return ExitError
			}
			root, command, watch := graphifyFor(*projectDir)
			if verb == "stop" && len(args) == 1 {
				ss, err := graphify.List(ctx, command)
				if err != nil {
					return fail(err)
				}
				for _, s := range ss {
					if strings.HasPrefix(s.ID, args[0]) {
						if err := graphify.Stop(ctx, command, s.ID); err != nil {
							return fail(err)
						}
						fmt.Fprintf(stdout, "Stopped %s (%s).\n", shortSession(s.ID), homeRelative(s.Root))
						return ExitOK
					}
				}
				return fail(fmt.Errorf("no session %s", args[0]))
			}
			if root == "" {
				return fail(fmt.Errorf("%s is not in a Git repository; pass --project", *projectDir))
			}
			n, err := graphify.Change(ctx, verb, root, command, watch, "harness providers sessions (by hand)")
			if err != nil {
				return fail(err)
			}
			switch {
			case verb == "stop":
				fmt.Fprintf(stdout, "Stopped %d session(s) of %s.\n", n, homeRelative(root))
			case n == 0:
				fmt.Fprintf(stdout, "%s already has a session (harness providers sessions restart to start afresh).\n", homeRelative(root))
			default:
				fmt.Fprintf(stdout, "Started a session for %s; it loads in the background (harness providers sessions).\n", homeRelative(root))
			}
			return ExitOK
		}
	}
}

