func syncFlags(fs *flag.FlagSet) action {
	projectDir := fs.String("project", ".", "directory inside the repository to sync")
	full := fs.Bool("full", false, "rescan every file instead of only what changed")
	since := fs.String("since", "", "compute changes from this commit instead of the last sync")
	return func(_ []string, stdout, stderr io.Writer) int {
		opts := project.SyncOptions{}
		switch {
		case *full && *since != "":
			fmt.Fprintln(stderr, "harness sync: --full and --since are mutually exclusive")
			return ExitUsage
		case *full:
			opts.Mode = gitsync.ModeFull
		case *since != "":
			opts.Mode, opts.Since = gitsync.ModeSince, *since
		}
		registry, err := syncRegistry(*projectDir)
		if err != nil {
			fmt.Fprintf(stderr, "harness sync: %v\n", err)
			return ExitError
		}
		defer registry.Close()
		for _, p := range registry.Providers() {
			if r, ok := p.(providers.Refresher); ok {
				opts.Refreshers = append(opts.Refreshers, r)
			}
		}

		res, err := project.SyncWith(context.Background(), *projectDir, opts)
		if err != nil {
			fmt.Fprintf(stderr, "harness sync: %v\n", err)
			return ExitError
		}
		reg := res.Registration
		head := describeHead(reg.Worktree)
		fmt.Fprintf(stdout, "Project   %s\n", reg.Project.ID)
		fmt.Fprintf(stdout, "Worktree  %s %s\n", reg.Worktree.ID, reg.Worktree.Path)
		switch {
		case res.Previous == nil:
			fmt.Fprintf(stdout, "Git       %s (worktree newly registered)\n", head)
		case res.HeadChanged():
			fmt.Fprintf(stdout, "Git       %s (was %s)\n", head, describeHead(*res.Previous))
		default:
			fmt.Fprintf(stdout, "Git       %s (unchanged)\n", head)
		}
		switch {
		case reg.Moved:
			fmt.Fprintf(stdout, "Note      project moved from %s; location updated\n", reg.PreviousRoot)
		case reg.Copied:
			fmt.Fprintf(stdout, "Note      copy of %s: new project id (copied from %s)\n", reg.PreviousRoot, reg.Project.CopiedFrom)
		}
		st := res.State
		dirty := "clean"
		if st.Dirty {
			dirty = fmt.Sprintf("dirty (%d uncommitted path(s))", st.DirtyPaths)
		}
		fmt.Fprintf(stdout, "State     recorded %s, working tree %s\n", describeHead(reg.Worktree), dirty)
		if res.CoveredBy != 0 {
			fmt.Fprintf(stdout, "Files     already synced to this HEAD by a concurrent run (#%d)\n", res.CoveredBy)
		} else {
			printFileSync(stdout, res.Files)
		}
		if c := res.Context; c.Calls > 0 {
			fmt.Fprintf(stdout, "Context   scored %d get_context answer(s): %d of %d changed file(s) were in the context\n", c.Calls, c.Hits, c.Changed)
		}
		for _, w := range res.Removed {
			fmt.Fprintf(stdout, "Removed   worktree %s %s (its git directory is gone)\n", w.ID, w.Path)
		}
		// architecture findings: a snapshot when they changed (TASK-0030)
		if db, done, err := openProjectDB(*projectDir); err == nil {
			for _, s := range findings.Sync(context.Background(), db, registry, reg.Worktree.Path, reg.Project.ID, reg.Worktree.Commit) {
				printFindings(stdout, s)
			}
			done()
		}
		fmt.Fprintln(stdout, "\nSynced.")
		sendTelemetryLater() // opt-in only; in the background
		return ExitOK
	}
}

func taskAdd(fs *flag.FlagSet) taskRun {
	title := fs.String("title", "", "what the task is (required)")
	goal := fs.String("goal", "", "the outcome and why")
	typ := fs.String("type", "feature", "feature, bug, chore, spike, docs, test or process")
	priority := fs.String("priority", "medium", "low, medium, high or critical")
	milestone := fs.String("milestone", "", "milestone id, e.g. M15")
	id := fs.String("id", "", "the task id (default: the next free one of --prefix)")
	prefix := fs.String("prefix", "", "id prefix (default: the prefix of the backlog's newest task, else TASK)")
	var deps, accept, scope multiFlag
	fs.Var(&deps, "depends", "a task it waits for (repeatable or comma-separated)")
	fs.Var(&accept, "accept", "an acceptance criterion that can be checked (repeatable)")
	fs.Var(&scope, "scope", "a path it may touch (repeatable or comma-separated)")
	return func(c *taskCtx, args []string) error {
		if strings.TrimSpace(*title) == "" {
			return usageError{"--title is required"}
		}
		var crit []string
		for _, a := range accept {
			if a = strings.TrimSpace(a); a != "" {
				crit = append(crit, a)
			}
		}
		d := tasks.Definition{ID: *id, Title: *title, Goal: strings.TrimSpace(*goal), Type: *typ, Priority: *priority,
			Milestone: *milestone, DependsOn: splitList(deps, true), Acceptance: crit, Scope: splitList(scope, false)}
		t, err := c.store.Create(c.ctx, d, *prefix, tasks.Origin{By: c.actor.Name, Source: "cli", Detail: "added with harness tasks add"})
		if err != nil {
			return err
		}
		if c.json {
			return c.emit(map[string]any{"task": tasks.ViewOf(t)})
		}
		fmt.Fprintf(c.stdout, "Added %s (%s): %s\n", t.ID, t.Status, t.Title)
		fmt.Fprintln(c.stdout, "Write it into the backlog file with: harness tasks export")
		return nil
	}
}

