func taskComplete(fs *flag.FlagSet) taskRun {
	summary := fs.String("summary", "", "what changed (required)")
	commit := fs.String("commit", "", "commit id")
	var accs, checks multiFlag
	fs.Var(&accs, "acc", `acceptance result "N=pass[:evidence]", "N=n/a:why" (repeat for each criterion)`)
	accAll := fs.String("acc-all", "", `report every criterion at once, e.g. "pass:see tests"`)
	fs.Var(&checks, "check", `validation "command=pass" (repeatable)`)
	return func(c *taskCtx, args []string) error {
		id := strings.ToUpper(args[0])
		t, err := c.store.Get(c.ctx, id)
		if err != nil {
			return err
		}
		in := tasks.CompleteInput{Summary: *summary, Commit: *commit}
		if *accAll != "" {
			res, ev, _ := strings.Cut(*accAll, ":")
			for _, a := range t.Acceptance {
				in.Acceptance = append(in.Acceptance, tasks.Report{Index: a.Index, Result: tasks.Result(res), Evidence: ev})
			}
		}
		for _, a := range accs {
			r, err := parseAcc(a)
			if err != nil {
				return usageError{err.Error()}
			}
			in.Acceptance = append(in.Acceptance, r)
		}
		for _, ch := range checks {
			cmd, res, ok := strings.Cut(ch, "=")
			if !ok {
				return usageError{fmt.Sprintf("--check %q: want command=pass", ch)}
			}
			in.Checks = append(in.Checks, tasks.Check{Command: cmd, Result: res})
		}
		done, unlocked, err := c.store.Complete(c.ctx, id, c.actor, in)
		if err != nil {
			return err
		}
		if c.json {
			return c.emit(map[string]any{"task": tasks.ViewOf(done), "unlocked": unlocked})
		}
		fmt.Fprintf(c.stdout, "Completed %s.\n", done.ID)
		if len(unlocked) > 0 {
			fmt.Fprintf(c.stdout, "Now ready: %s\n", strings.Join(unlocked, ", "))
		}
		return nil
	}
}

