func taskExport(fs *flag.FlagSet) taskRun {
	dryRun := fs.Bool("dry-run", false, "say what would be written, write nothing")
	return func(c *taskCtx, args []string) error {
		file := filepath.Join(c.root, "docs", "backlog.yaml")
		if len(args) > 0 {
			file = args[0]
		}
		res, err := c.store.Export(c.ctx, file, *dryRun)
		if err != nil {
			return err
		}
		if c.json {
			return c.emit(map[string]any{"dry_run": *dryRun, "export": res})
		}
		switch {
		case len(res.Added) == 0 && !res.Created:
			fmt.Fprintf(c.stdout, "%s already holds every task.\n", file)
		case *dryRun:
			fmt.Fprintf(c.stdout, "Would write %d task(s) into %s: %s\n", len(res.Added), file, strings.Join(res.Added, ", "))
		default:
			fmt.Fprintf(c.stdout, "Wrote %d task(s) into %s: %s\n", len(res.Added), file, strings.Join(res.Added, ", "))
		}
		return nil
	}
}

func taskFlags(name string, flags func(*flag.FlagSet) taskRun) func(*flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		run := flags(fs)
		projectDir, asJSON := projectFlags(fs)
		return func(args []string, stdout, stderr io.Writer) int {
			tc, err := openTaskCtx(*projectDir, stdout, *asJSON)
			if err != nil {
				fmt.Fprintf(stderr, "harness tasks %s: %v\n", name, err)
				return ExitError
			}
			defer tc.close()
			if err := run(tc, args); err != nil {
				fmt.Fprintf(stderr, "harness tasks %s: %v\n", name, err)
				var ue usageError
				if errors.As(err, &ue) {
					return ExitUsage
				}
				return ExitError
			}
			return ExitOK
		}
	}
}

func taskImport(fs *flag.FlagSet) taskRun {
	dryRun := fs.Bool("dry-run", false, "validate and report without writing")
	return func(c *taskCtx, args []string) error {
		var file string
		if len(args) > 0 {
			file = args[0]
		}
		if file == "" {
			file = filepath.Join(c.root, "docs", "backlog.yaml")
		}
		b, err := tasks.ReadBacklog(file)
		if err != nil {
			return err
		}
		source := file
		if rel, err := filepath.Rel(c.root, file); err == nil && !strings.HasPrefix(rel, "..") {
			source = rel
		}
		res, err := c.store.Import(c.ctx, b.Tasks, source, *dryRun)
		if err != nil {
			return err
		}
		milestones, err := c.store.ImportMilestones(c.ctx, b.Milestones, source, *dryRun)
		if err != nil {
			return err
		}
		if c.json {
			return c.emit(map[string]any{"dry_run": *dryRun, "added": res.Added, "updated": res.Updated,
				"unchanged": len(res.Unchanged), "orphaned": res.Orphaned, "unlocked": res.Unlocked, "milestones_changed": milestones})
		}
		verb := "Imported"
		if *dryRun {
			verb = "Would import"
		}
		fmt.Fprintf(c.stdout, "%s %s: %d added, %d updated, %d unchanged.\n", verb, source, len(res.Added), len(res.Updated), len(res.Unchanged))
		if milestones > 0 {
			fmt.Fprintf(c.stdout, "Milestones added or changed: %d\n", milestones)
		}
		if len(res.Updated) > 0 {
			fmt.Fprintf(c.stdout, "Updated: %s\n", strings.Join(res.Updated, ", "))
		}
		if len(res.Unlocked) > 0 {
			fmt.Fprintf(c.stdout, "Ready: %s\n", strings.Join(res.Unlocked, ", "))
		}
		if len(res.Orphaned) > 0 {
			fmt.Fprintf(c.stdout, "In the database but not in the file (kept): %s\n", strings.Join(res.Orphaned, ", "))
		}
		return nil
	}
}

func taskList(fs *flag.FlagSet) taskRun {
	var statuses multiFlag
	fs.Var(&statuses, "status", "filter by status (repeatable or comma-separated)")
	milestone := fs.String("milestone", "", "filter by milestone")
	all := fs.Bool("all", false, "include done tasks")
	return func(c *taskCtx, args []string) error {
		var f tasks.Filter
		for _, s := range statuses {
			for _, part := range strings.Split(s, ",") {
				st, err := tasks.ParseStatus(part)
				if err != nil {
					return usageError{err.Error()}
				}
				f.Statuses = append(f.Statuses, st)
			}
		}
		if len(f.Statuses) == 0 && !*all {
			f.Statuses = []tasks.Status{tasks.Backlog, tasks.Ready, tasks.Claimed, tasks.InProgress, tasks.Review, tasks.Blocked}
		}
		f.Milestone = *milestone
		list, err := c.store.List(c.ctx, f)
		if err != nil {
			return err
		}
		if c.json {
			views := make([]tasks.View, len(list))
			for i, t := range list {
				views[i] = tasks.ViewOf(t)
			}
			return c.emit(map[string]any{"tasks": views})
		}
		if len(list) == 0 {
			fmt.Fprintln(c.stdout, "No tasks match.")
			return nil
		}
		fmt.Fprintf(c.stdout, "%-10s %-11s %-6s %-8s %s\n", "ID", "STATUS", "MS", "PRIORITY", "TITLE")
		for _, t := range list {
			extra := ""
			if t.Claimant != "" {
				extra = "  [" + t.Claimant + "]"
			}
			if t.Status == tasks.Blocked || t.Status == tasks.Deferred {
				extra = "  [" + string(t.Status) + ": " + t.BlockedReason + "]"
			}
			fmt.Fprintf(c.stdout, "%-10s %-11s %-6s %-8s %s%s\n", t.ID, t.Status, t.Milestone, t.Priority, t.Title, extra)
		}
		return nil
	}
}

