		for _, p := range ps {
			fmt.Fprintf(c.stdout, "%s  [%s] %s  (by %s)\n", p.ID, p.Status, p.Task.Title, p.ProposedBy)
			if p.Task.Goal != "" {
				fmt.Fprintf(c.stdout, "    goal: %s\n", p.Task.Goal)
			}
			if p.Reason != "" {
				fmt.Fprintf(c.stdout, "    why:  %s\n", p.Reason)
			}
			for i, a := range p.Task.Acceptance {
				fmt.Fprintf(c.stdout, "    %d. %s\n", i+1, a)
			}
			if p.Result != "" {
				fmt.Fprintf(c.stdout, "    became %s\n", p.Result)
			}
		}
		if *status == tasks.ProposalPending {
			fmt.Fprintln(c.stdout, "\nharness tasks approve <id> creates the task; harness tasks reject <id> --note \"why\" closes it.")
		}
		return nil
	}
