func telemetryCommand() command {
	return command{name: "telemetry", summary: "Opt-in export of aggregated usage reports to the harness developer (off by default)",
		about: "Sends only report numbers (tool and provider rates, context relevance, knowledge use, findings without paths) " +
			"and versions, under random ids; never code, paths, queries, task text, memories or project names. " +
			"'preview' prints exactly what would be sent.",
		subs: []command{
			{name: "status", summary: "Show whether the export is on, where it goes and when it last sent (the default)", flags: telemetryStatusFlags},
			{name: "enable", summary: "Turn the export on for this machine", flags: telemetryEnableFlags},
			{name: "disable", summary: "Turn the export off (nothing more is sent)", flags: telemetryDisableFlags},
			{name: "preview", summary: "Print exactly what would be sent, without sending", flags: telemetryPreviewFlags},
			{name: "send", summary: "Send now (with --auto: only if on and the last send is over a day old; never fails)", flags: telemetrySendFlags},
		},
		defaultSub: "status"}
}

func telemetryDisableFlags(*flag.FlagSet) action {
	return func(_ []string, stdout, stderr io.Writer) int {
		st, err := devtelemetry.Load()
		if err == nil {
			st.Enabled = false
			err = devtelemetry.Save(st)
		}
		if err != nil {
			fmt.Fprintf(stderr, "harness telemetry disable: %v\n", err)
			return ExitError
		}
		fmt.Fprintln(stdout, "Telemetry export off: nothing more is sent.")
		return ExitOK
	}
}

func telemetryEnableFlags(fs *flag.FlagSet) action {
	endpoint := fs.String("endpoint", "", "the collector's URL (a harness-collect server), e.g. http://host:8766/v1/report")
	token := fs.String("token", "", "shared token the collector expects (optional)")
	return func(_ []string, stdout, stderr io.Writer) int {
		if *endpoint == "" {
			fmt.Fprintln(stderr, "harness telemetry enable: --endpoint is required")
			return ExitUsage
		}
		st, err := devtelemetry.Load()
		if err == nil {
			err = devtelemetry.Enable(&st, *endpoint, *token)
		}
		if err == nil {
			err = devtelemetry.Save(st)
		}
		if err != nil {
			fmt.Fprintf(stderr, "harness telemetry enable: %v\n", err)
			return ExitError
		}
		fmt.Fprintf(stdout, "Telemetry export on: aggregated reports go to %s at most daily, after a sync.\n", *endpoint)
		fmt.Fprintln(stdout, "'harness telemetry preview' shows exactly what is sent; 'harness telemetry disable' stops it.")
		return ExitOK
	}
}

func telemetryPreviewFlags(*flag.FlagSet) action {
	return func(_ []string, stdout, stderr io.Writer) int {
		st, err := devtelemetry.Load()
		if err != nil {
			fmt.Fprintf(stderr, "harness telemetry preview: %v\n", err)
			return ExitError
		}
		if st.Machine == "" {
			st.Machine = "m_(assigned when enabled)"
		}
		body := devtelemetry.Encode(telemetryPayload(context.Background(), &st, time.Now()))
		stdout.Write(body)
		return ExitOK
	}
}

func telemetrySendFlags(fs *flag.FlagSet) action {
	auto := fs.Bool("auto", false, "only if enabled and the last send is over a day old; quiet, never fails (run after syncs)")
	return func(_ []string, stdout, stderr io.Writer) int {
		st, err := devtelemetry.Load()
		now := time.Now()
		if *auto {
			// Whatever happens, an automatic send never affects harness.
			if err == nil && st.Due(now) {
				body := devtelemetry.Encode(telemetryPayload(context.Background(), &st, now))
				if devtelemetry.Send(context.Background(), &st, body, now) == nil {
					devtelemetry.Save(st)
				}
			}
			return ExitOK
		}
		if err != nil {
			fmt.Fprintf(stderr, "harness telemetry send: %v\n", err)
			return ExitError
		}
		if !st.Enabled {
			fmt.Fprintln(stderr, "harness telemetry send: the export is off ('harness telemetry enable --endpoint URL')")
			return ExitUsage
		}
		body := devtelemetry.Encode(telemetryPayload(context.Background(), &st, now))
		if err := devtelemetry.Send(context.Background(), &st, body, now); err != nil {
			devtelemetry.Save(st) // keep the project ids assigned
			fmt.Fprintf(stderr, "harness telemetry send: %v (logged; nothing else is affected)\n", err)
			return ExitError
		}
		devtelemetry.Save(st)
		fmt.Fprintf(stdout, "Sent %d bytes to %s.\n", len(body), st.Endpoint)
		return ExitOK
	}
}

func telemetryStatusFlags(*flag.FlagSet) action {
	return func(_ []string, stdout, stderr io.Writer) int {
		st, err := devtelemetry.Load()
		if err != nil {
			fmt.Fprintf(stderr, "harness telemetry: %v\n", err)
			return ExitError
		}
		if !st.Enabled {
			fmt.Fprintln(stdout, "Telemetry export: off (nothing is sent). 'harness telemetry enable --endpoint URL' turns it on;")
			fmt.Fprintln(stdout, "'harness telemetry preview' shows what it would send.")
			return ExitOK
		}
		last := "never"
		if st.LastSent != nil {
			last = st.LastSent.Local().Format("2006-01-02 15:04")
		}
		logPath, _ := devtelemetry.LogPath()
		fmt.Fprintf(stdout, "Telemetry export: on\n  endpoint  %s\n  machine   %s (random id)\n  last sent %s (at most daily, after a sync)\n  log       %s\n",
			st.Endpoint, st.Machine, last, homeRelative(logPath))
		return ExitOK
	}
}

func uiFlags(fs *flag.FlagSet) action {
	addr := fs.String("addr", "127.0.0.1:7477", "loopback address to listen on (port 0 picks a free one)")
	noOpen := fs.Bool("no-open", false, "only print the URL, do not open a browser")
	return func(_ []string, stdout, stderr io.Writer) int {
		host, _, err := net.SplitHostPort(*addr)
		if err != nil || !gui.IsLoopback(host) {
			fmt.Fprintf(stderr, "harness ui: --addr %q must be a loopback host and port, e.g. 127.0.0.1:7477\n", *addr)
			return ExitUsage
		}
		ln, err := net.Listen("tcp", *addr)
		if err != nil {
			fmt.Fprintf(stderr, "harness ui: %v (another harness ui running? try --addr 127.0.0.1:0)\n", err)
			return ExitError
		}
		url := "http://" + ln.Addr().String() + "/"
		fmt.Fprintf(stdout, "harness ui on %s (Ctrl-C to stop)\n", url)
		if !*noOpen {
			if err := openBrowser(url); err != nil {
				fmt.Fprintf(stderr, "harness ui: could not open a browser (%v); open %s\n", err, url)
			}
		}
		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()
		if err := gui.Serve(ctx, ln); err != nil && !errors.Is(err, context.Canceled) {
			fmt.Fprintf(stderr, "harness ui: %v\n", err)
			return ExitError
		}
		return ExitOK
	}
}

func versionFlags(fs *flag.FlagSet) action {
	jsonFlag := fs.Bool("json", false, "machine-readable output")
	return func(_ []string, stdout, stderr io.Writer) int {
		asJSON := *jsonFlag

		info := buildinfo.Get()
		if asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			if err := enc.Encode(info); err != nil {
				fmt.Fprintf(stderr, "harness version: %v\n", err)
				return ExitError
			}
			return ExitOK
		}
		fmt.Fprintln(stdout, info.String())
		return ExitOK
	}
}

func workspaceAdoptionFlags(fs *flag.FlagSet) action {
	projectDir, asJSON := projectFlags(fs)
	deep := fs.Bool("deep", false, "every provider of every member (slower)")
	return func(args []string, stdout, stderr io.Writer) int {
		ws, closeWS, err := cliSearcher(*projectDir, true)
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace adoption: %v\n", err)
			return ExitError
		}
		defer closeWS()
		rep, err := ws.Adoption(context.Background(), args[0], *deep)
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace adoption: %v\n", err)
			return ExitError
		}
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(rep)
			return ExitOK
		}
		fmt.Fprintf(stdout, "%s: packages %s; imported as %s; %d public types\n", rep.Library,
			orNone(rep.Packages), orNone(rep.Namespaces), rep.PublicTypes)
		for _, c := range rep.Consumers {
			fmt.Fprintf(stdout, "\n%s uses it\n", c.Project)
			for _, r := range c.Packages {
				fmt.Fprintf(stdout, "  package %-40s %s:%d\n", r.Matched, r.Path, r.Line)
			}
			if c.ImportFiles > 0 {
				fmt.Fprintf(stdout, "  %d file(s) import %s\n", c.ImportFiles, strings.Join(c.Namespaces, ", "))
			}
		}
		if len(rep.NonConsumers) > 0 {
			fmt.Fprintf(stdout, "\nNo reference found in: %s\n", strings.Join(rep.NonConsumers, ", "))
		}
		if len(rep.Twins) > 0 {
			fmt.Fprintln(stdout, "\nTypes named like the library's public ones (possible local implementations):")
			for _, t := range rep.Twins {
				fmt.Fprintf(stdout, "  %s:%s:%d  %s %s  (library %s:%d)\n", t.Project, t.Decl.Path, t.Decl.Line, t.Decl.Kind, t.Decl.Name, t.Library.Path, t.Library.Line)
			}
		}
		for _, n := range rep.Notes {
			fmt.Fprintln(stdout, "note: "+n)
		}
		return ExitOK
	}
}

func workspaceCommand() command {
	name := func(n, summary string, flags func(*flag.FlagSet) action) command {
		return command{name: n, summary: summary, args: "<workspace>", minArgs: 1, maxArgs: 1, flags: flags}
	}
	return command{name: "workspace", aliases: []string{"workspaces"},
		summary: "Group this machine's projects into workspaces for cross-project search (list, create, join...)",
		about:   "Workspaces live on this machine (workspaces.json next to the project registry); members keep their own state.",
		subs: []command{
			{name: "list", summary: "List workspaces and their members (the default)", flags: workspaceListFlags},
			name("create", "Create a workspace; --discover DIR adds the registered projects under a folder", workspaceCreateFlags),
			{name: "rename", summary: "Change a workspace's short name (--to) or display name (--title)",
				args: "<name>", minArgs: 1, maxArgs: 1, flags: workspaceRenameFlags},
			name("show", "Show a workspace's members", workspaceShowFlags),
			name("join", "Add a project (--project, default: this repository) to a workspace", workspaceJoinFlags(true)),
			name("leave", "Remove a project from a workspace (its state is untouched)", workspaceJoinFlags(false)),
			name("delete", "Delete a workspace (its members' state is untouched)", workspaceDeleteFlags),
			{name: "adoption", summary: "Which members use a library member, and which declare types named like its public ones",
				args: "<library>", minArgs: 1, maxArgs: 1, flags: workspaceAdoptionFlags},
			{name: "concern", summary: "Each member's code, decisions and dependencies about one concern, side by side",
				args: "<words...>", minArgs: 1, maxArgs: -1, flags: workspaceConcernFlags},
		},
		defaultSub: "list"}
}

func workspaceConcernFlags(fs *flag.FlagSet) action {
	projectDir, asJSON := projectFlags(fs)
	deep := fs.Bool("deep", false, "every provider of every member (slower)")
	return func(args []string, stdout, stderr io.Writer) int {
		ws, closeWS, err := cliSearcher(*projectDir, true)
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace concern: %v\n", err)
			return ExitError
		}
		defer closeWS()
		rep := ws.Concern(context.Background(), strings.Join(args, " "), *deep)
		if *asJSON {
			enc := json.NewEncoder(stdout)
			enc.SetIndent("", "  ")
			enc.Encode(rep)
			return ExitOK
		}
		fmt.Fprintf(stdout, "Concern %q (words: %s)\n", rep.Concern, orNone(rep.Words))
		for _, m := range rep.Members {
			fmt.Fprintf(stdout, "\n%s\n", m.Project)
			if len(m.Code)+len(m.Decisions)+len(m.Dependencies) == 0 {
				fmt.Fprintln(stdout, "  nothing found")
				continue
			}
			for _, c := range m.Code {
				fmt.Fprintf(stdout, "  code        %-40s %s:%d (%s)\n", c.Name, c.Path, c.Line, c.Provider)
			}
			for _, d := range m.Decisions {
				fmt.Fprintf(stdout, "  %-11s %s  [%s]\n", d.Type, d.Content, d.ID)
			}
			for _, d := range m.Dependencies {
				fmt.Fprintf(stdout, "  dependency  %-40s %s:%d\n", d.Package, d.Path, d.Line)
			}
		}
		for _, n := range rep.Notes {
			fmt.Fprintln(stdout, "note: "+n)
		}
		return ExitOK
	}
}

func workspaceCreateFlags(fs *flag.FlagSet) action {
	discover := fs.String("discover", "", "add every registered project under this folder")
	title := fs.String("title", "", "display name shown in harness ui (any text)")
	return func(args []string, stdout, stderr io.Writer) int {
		w, err := workspace.Create(args[0])
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace create: %v\n", err)
			return ExitError
		}
		if *title != "" {
			if w, err = workspace.Rename(w.Name, "", title); err != nil {
				fmt.Fprintf(stderr, "harness workspace create: %v\n", err)
				return ExitError
			}
		}
		fmt.Fprintf(stdout, "Created workspace %s.\n", w.Name)
		if *discover == "" {
			fmt.Fprintf(stdout, "Add projects: harness workspace join %s --project <repository>\n", w.Name)
			return ExitOK
		}
		reg, err := machine.Load()
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace create: %v\n", err)
			return ExitError
		}
		dir, found := workspace.Discover(reg, *discover)
		var ids []string
		for _, p := range found {
			ids = append(ids, p.ID)
			fmt.Fprintf(stdout, "  + %s  %s\n", p.ShortName(), p.Root)
		}
		if len(ids) == 0 {
			fmt.Fprintf(stdout, "No registered projects under %s ('harness init' in a repository registers it).\n", dir)
			return ExitOK
		}
		if _, err := workspace.Join(w.Name, ids...); err != nil {
			fmt.Fprintf(stderr, "harness workspace create: %v\n", err)
			return ExitError
		}
		fmt.Fprintf(stdout, "Joined %d project(s); 'harness workspace leave %s --project <repository>' removes one.\n", len(ids), w.Name)
		return ExitOK
	}
}

func workspaceDeleteFlags(*flag.FlagSet) action {
	return func(args []string, stdout, stderr io.Writer) int {
		if err := workspace.Delete(args[0]); err != nil {
			fmt.Fprintf(stderr, "harness workspace delete: %v\n", err)
			return ExitError
		}
		fmt.Fprintf(stdout, "Deleted workspace %s (its projects and their state are untouched).\n", args[0])
		return ExitOK
	}
}

func workspaceJoinFlags(join bool) func(*flag.FlagSet) action {
	return func(fs *flag.FlagSet) action {
		projectDir := fs.String("project", ".", "repository to add or remove")
		return func(args []string, stdout, stderr io.Writer) int {
			verb := map[bool]string{true: "join", false: "leave"}[join]
			p, err := registeredProject(*projectDir)
			if err != nil {
				fmt.Fprintf(stderr, "harness workspace %s: %v\n", verb, err)
				return ExitError
			}
			name := p.ShortName()
			if join {
				added, err := workspace.Join(args[0], p.ID)
				switch {
				case err != nil:
					fmt.Fprintf(stderr, "harness workspace join: %v\n", err)
					return ExitError
				case len(added) == 0:
					fmt.Fprintf(stdout, "%s is already in %s.\n", name, args[0])
				default:
					fmt.Fprintf(stdout, "%s joined %s.\n", name, args[0])
				}
				return ExitOK
			}
			was, err := workspace.Leave(args[0], p.ID)
			switch {
			case err != nil:
				fmt.Fprintf(stderr, "harness workspace leave: %v\n", err)
				return ExitError
			case !was:
				fmt.Fprintf(stdout, "%s is not in %s.\n", name, args[0])
			default:
				fmt.Fprintf(stdout, "%s left %s (its state is untouched).\n", name, args[0])
			}
			return ExitOK
		}
	}
}

func workspaceListFlags(*flag.FlagSet) action {
	return func(_ []string, stdout, stderr io.Writer) int {
		f, err := workspace.Load()
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace: %v\n", err)
			return ExitError
		}
		if len(f.Workspaces) == 0 {
			fmt.Fprintln(stdout, "No workspaces yet: 'harness workspace create <name> --discover <folder>' groups the projects under a folder.")
			return ExitOK
		}
		reg, _ := machine.Load()
		for _, w := range f.Workspaces {
			var names []string
			for _, m := range w.Members {
				n, _ := projectLabel(reg, m)
				names = append(names, n)
			}
			title := ""
			if w.Title != "" {
				title = " (" + w.Title + ")"
			}
			fmt.Fprintf(stdout, "%-20s %d project(s): %s%s\n", w.Name, len(w.Members), strings.Join(names, ", "), title)
		}
		return ExitOK
	}
}

func workspaceRenameFlags(fs *flag.FlagSet) action {
	to := fs.String("to", "", "new short name (lowercase letters, digits, '.', '_' or '-')")
	title := fs.String("title", "", "display name shown in harness ui (any text; \"\" with --clear-title removes it)")
	clear := fs.Bool("clear-title", false, "remove the display name")
	return func(args []string, stdout, stderr io.Writer) int {
		var t *string
		switch {
		case *clear:
			empty := ""
			t = &empty
		case *title != "":
			t = title
		}
		if *to == "" && t == nil {
			fmt.Fprintln(stderr, "harness workspace rename: give --to <new name>, --title <display name> or --clear-title")
			return ExitUsage
		}
		w, err := workspace.Rename(args[0], *to, t)
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace rename: %v\n", err)
			return ExitError
		}
		fmt.Fprintf(stdout, "Workspace %s", w.Name)
		if w.Title != "" {
			fmt.Fprintf(stdout, ", shown as %q", w.Title)
		}
		fmt.Fprintln(stdout, ".")
		if w.Name != args[0] {
			fmt.Fprintf(stdout, "Agents and commands now use workspace:%s; its members and knowledge are unchanged.\n", w.Name)
		}
		return ExitOK
	}
}

func workspaceShowFlags(*flag.FlagSet) action {
	return func(args []string, stdout, stderr io.Writer) int {
		f, err := workspace.Load()
		if err != nil {
			fmt.Fprintf(stderr, "harness workspace show: %v\n", err)
			return ExitError
		}
		w, ok := f.Find(args[0])
		if !ok {
			fmt.Fprintf(stderr, "harness workspace show: %v %q\n", workspace.ErrNotFound, args[0])
			return ExitError
		}
		reg, _ := machine.Load()
		fmt.Fprintf(stdout, "%s  (%s, %d project(s))\n", w.Name, w.ID, len(w.Members))
		if w.Title != "" {
			fmt.Fprintf(stdout, "  shown as %q\n", w.Title)
		}
		for _, m := range w.Members {
			n, root := projectLabel(reg, m)
			fmt.Fprintf(stdout, "  %-24s %s\n", n, root)
		}
		return ExitOK
	}
}
